using System;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using UnityEngine.AI;using Codice.Characters;using Codice.Bosses;using Codice.Mechanics;
public static class VerifyLabAggression {
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
 public static async Task<string> Run(){var room=UnityEngine.Object.FindAnyObjectByType<CombatTestRoom>();var p=RunDirector.Instance.Player;Check(room&&p,"Laboratory unavailable");if(SessionCheats.God)SessionCheats.Execute("Good!");Check(p.State.LaboratoryImmortal,"Immortality not set");int deaths=0;p.State.Died+=()=>deaths++;p.State.Damage(100000,true);Check(p.State.Health==1&&p.State.IsAlive&&deaths==0,"Lethal damage killed laboratory player");p.State.NetworkRevive();var outside=new CharacterState();outside.Initialize(PlayerClass.Warrior);outside.Damage(100000,true);Check(!outside.IsAlive,"Immortality leaked outside lab");
 var b=UnityEngine.Object.Instantiate(Resources.Load<GameObject>("ExpeditionEnemies/AngelKnight")).GetComponent<BossCharacter>();try{b.Initialize(p,1);b.enabled=false;var flags=BindingFlags.Instance|BindingFlags.NonPublic;var tick=typeof(BossCharacter).GetMethod("TickAngel",flags);var timer=typeof(BossCharacter).GetField("attackTimer",flags);var sequence=typeof(BossCharacter).GetField("sequence",flags);var agent=b.GetComponent<NavMeshAgent>();Check(NavMesh.SamplePosition(p.transform.position+p.transform.forward*10,out var hit,5,NavMesh.AllAreas),"No navigation");agent.Warp(hit.position);await Task.Delay(100);timer.SetValue(b,0f);sequence.SetValue(b,0);tick.Invoke(b,new object[]{.01f});Check(b.CurrentAttack==BossAttack.Charge,"Charge not selected");tick.Invoke(b,new object[]{.7f});Check(b.State==BossState.Charging,"Charge not started");var before=b.transform.position;tick.Invoke(b,new object[]{.1f});Check(Vector3.Distance(before,b.transform.position)>.1f,"Charge did not move");b.ApplyStun(.2f);tick.Invoke(b,new object[]{.01f});Check(b.State==BossState.Recovery,"Charge not canceled by stun");tick.Invoke(b,new object[]{1f});timer.SetValue(b,0f);sequence.SetValue(b,4);tick.Invoke(b,new object[]{.01f});Check(b.CurrentAttack==BossAttack.RadiantRain,"Judgment not selected");tick.Invoke(b,new object[]{1f});Check(UnityEngine.Object.FindObjectsByType<AngelJudgment>(FindObjectsSortMode.None).Length>=4,"Judgment marks missing");b.ApplyStun(.2f);await Task.Delay(100);Check(UnityEngine.Object.FindObjectsByType<AngelJudgment>(FindObjectsSortMode.None).Length==0,"Stun left delayed hits");Debug.Log("[LabAggressionTest] PASS immortality scoped to lab, charge movement, judgment marks, stun cancellation");return "PASS lab immortality, normal death outside, charge and judgment cancellation";}finally{if(b)UnityEngine.Object.Destroy(b.gameObject);p.State.NetworkRevive();}}
}
